  /// Which state wins when several hold, highest first: the MUI recipe's cascade, read backwards.
  static const List<String> statePrecedence = [
    'disabled',
    'loading',
    'focus',
    'pressed',
    'hover',
  ];

  static bool _holds(
    String state,
    SolarIconButtonProps p,
    Set<WidgetState> s,
  ) => switch (state) {
    'disabled' =>
      p.disabled || (!p.loading && s.contains(WidgetState.disabled)),
    'loading' => p.loading,
    'focus' => s.contains(WidgetState.focused),
    'pressed' => s.contains(WidgetState.pressed),
    'hover' => s.contains(WidgetState.hovered),
    _ => false,
  };

  /// The entry for one cell under these props and states, by the IR's precedence: a state that
  /// holds beats the resting value, the per-size-and-appearance entry beats the per-appearance
  /// one, and the resting value falls back through appearance, size and base.
  static String? lookup(
    String cell,
    SolarIconButtonProps p,
    Set<WidgetState> s,
  ) {
    final combo = 'shape=${p.shape.name}, variant=${p.variant.name}';
    final size = p.size.name;
    for (final state in statePrecedence) {
      if (!_holds(state, p, s)) continue;
      final hit =
          cells['$cell|combined|$size|$combo|$state'] ??
          cells['$cell|appearance|$combo|$state'];
      if (hit != null) return hit;
    }
    return cells['$cell|combined|$size|$combo|default'] ??
        cells['$cell|appearance|$combo|default'] ??
        cells['$cell|size|$size'] ??
        cells['$cell|base'];
  }

  static Color color(
    SolarTheme t,
    String cell,
    SolarIconButtonProps p,
    Set<WidgetState> s,
  ) {
    final c = t.colors;
    return switch (lookup(cell, p, s)) {
      'none' => Colors.transparent,
      't:color.action.primary.bg.active' => c.actionPrimaryBgActive,
      't:color.action.primary.bg.default' => c.actionPrimaryBgDefault,
      't:color.action.primary.bg.disabled' => c.actionPrimaryBgDisabled,
      't:color.action.primary.bg.hover' => c.actionPrimaryBgHover,
      't:color.action.primary.icon.active' => c.actionPrimaryIconActive,
      't:color.action.primary.icon.default' => c.actionPrimaryIconDefault,
      't:color.action.primary.icon.disabled' => c.actionPrimaryIconDisabled,
      't:color.action.primary.icon.hover' => c.actionPrimaryIconHover,
      't:color.action.secondary.bg.active' => c.actionSecondaryBgActive,
      't:color.action.secondary.bg.default' => c.actionSecondaryBgDefault,
      't:color.action.secondary.bg.hover' => c.actionSecondaryBgHover,
      't:color.action.secondary.icon.active' => c.actionSecondaryIconActive,
      't:color.action.secondary.icon.default' => c.actionSecondaryIconDefault,
      't:color.action.secondary.icon.disabled' => c.actionSecondaryIconDisabled,
      't:color.action.secondary.icon.hover' => c.actionSecondaryIconHover,
      't:color.action.tertiary.bg.active' => c.actionTertiaryBgActive,
      't:color.action.tertiary.bg.default' => c.actionTertiaryBgDefault,
      't:color.action.tertiary.bg.hover' => c.actionTertiaryBgHover,
      't:color.action.tertiary.icon.active' => c.actionTertiaryIconActive,
      't:color.action.tertiary.icon.default' => c.actionTertiaryIconDefault,
      't:color.action.tertiary.icon.disabled' => c.actionTertiaryIconDisabled,
      't:color.action.tertiary.icon.hover' => c.actionTertiaryIconHover,
      't:color.border.disabled' => c.borderDisabled,
      't:color.border.medium' => c.borderMedium,
      final v => throw StateError('$cell: no colour for $v'),
    };
  }

  static List<BoxShadow> shadow(
    SolarTheme t,
    String cell,
    SolarIconButtonProps p,
    Set<WidgetState> s,
  ) => switch (lookup(cell, p, s)) {
    'none' || null => const <BoxShadow>[],
    't:shadow.control' => t.shadows.control,
    't:shadow.focus.default' => t.shadows.focusDefault,
    final v => throw StateError('$cell: no shadow for $v'),
  };

  /// A length in logical pixels, or null where the IR says the layer hugs its content.
  static double? dimension(
    String cell,
    SolarIconButtonProps p,
    Set<WidgetState> s,
  ) {
    final v = lookup(cell, p, s);
    if (v == null || v == 'k:HUG') return null;
    if (v == 'k:FILL') return double.infinity;
    if (v.startsWith('px:')) return double.parse(v.substring(3));
    return switch (v) {
      't:border.default' => SolarBorder.$default,
      't:icon.md' => SolarIconSize.md,
      't:icon.sm' => SolarIconSize.sm,
      't:icon.xs' => SolarIconSize.xs,
      't:inset.none' => SolarInset.none,
      't:radius.control' => SolarRadius.control,
      't:radius.pill' => SolarRadius.pill,
      _ => throw StateError('$cell: no length for $v'),
    };
  }

  static TextStyle? textStyle(
    SolarTheme t,
    String cell,
    SolarIconButtonProps p,
    Set<WidgetState> s,
  ) => switch (lookup(cell, p, s)) {
    'none' || null => null,

    final v => throw StateError('$cell: no text style for $v'),
  };

  /// Whether a layer is drawn: the shell reads this, the style does not.
  static bool present(
    String layer,
    SolarIconButtonProps p,
    Set<WidgetState> s,
  ) => lookup('$layer.present', p, s) != 'b:false';

  static BorderSide _side(
    SolarTheme t,
    SolarIconButtonProps p,
    Set<WidgetState> s,
  ) {
    final width = lookup('root.borderWidth', p, s);
    if (width == null || width == 'none') return BorderSide.none;
    return BorderSide(
      color: color(t, 'root.borderColor', p, s),
      width: dimension('root.borderWidth', p, s)!,
    );
  }

  static BorderRadius _radius(SolarIconButtonProps p, Set<WidgetState> s) =>
      BorderRadius.circular(dimension('root.radius', p, s) ?? 0);

  /// A [ButtonStyle] for a IconButton that draws SOLAR's Icon Button.
  ///
  /// The background and the shadows are painted by one [BoxDecoration] in [ButtonStyle.backgroundBuilder]:
  /// ButtonStyle has elevation but no box shadows, and a Flutter shadow paints under the whole
  /// box, so drawing it over a separately coloured Material would darken the button's face, which
  /// CSS never does. Material's own overlay, splash and density are switched off, because every
  /// SOLAR state has its own explicit colours and sizes.
  static ButtonStyle style(
    SolarTheme t, [
    SolarIconButtonProps p = const SolarIconButtonProps(),
  ]) {
    WidgetStateProperty<T> by<T>(T Function(Set<WidgetState> s) f) =>
        WidgetStateProperty.resolveWith(f);
    const none = <WidgetState>{};
    final width = dimension('root.width', p, none);
    final height = dimension('root.height', p, none);
    return ButtonStyle(
      backgroundColor: const WidgetStatePropertyAll(Colors.transparent),
      foregroundColor: by((s) => color(t, 'icon.color', p, s)),
      iconColor: by((s) => color(t, 'icon.color', p, s)),
      iconSize: WidgetStatePropertyAll(dimension('icon.width', p, none)),
      padding: by(
        (s) => EdgeInsetsDirectional.only(
          start: dimension('root.paddingLeft', p, s) ?? 0,
          end: dimension('root.paddingRight', p, s) ?? 0,
          top: dimension('root.paddingTop', p, s) ?? 0,
          bottom: dimension('root.paddingBottom', p, s) ?? 0,
        ),
      ),
      minimumSize: WidgetStatePropertyAll(Size(width ?? 0, height ?? 0)),
      fixedSize: width == null
          ? null
          : WidgetStatePropertyAll(Size(width, height ?? 0)),
      side: by((s) => _side(t, p, s)),
      shape: by((s) => RoundedRectangleBorder(borderRadius: _radius(p, s))),
      elevation: const WidgetStatePropertyAll(0),
      shadowColor: const WidgetStatePropertyAll(Colors.transparent),
      surfaceTintColor: const WidgetStatePropertyAll(Colors.transparent),
      overlayColor: const WidgetStatePropertyAll(Colors.transparent),
      splashFactory: NoSplash.splashFactory,
      visualDensity: VisualDensity.standard,
      backgroundBuilder: (context, s, child) => DecoratedBox(
        decoration: BoxDecoration(
          color: color(t, 'root.background', p, s),
          borderRadius: _radius(p, s),
          boxShadow: shadow(t, 'root.shadow', p, s),
        ),
        child: child,
      ),
    );
  }
}
